CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','TEACHER','STUDENT')), name TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS teachers(id SERIAL PRIMARY KEY, user_id INT UNIQUE REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS students(id SERIAL PRIMARY KEY, user_id INT UNIQUE REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, teacher_id INT REFERENCES teachers(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS enrollments(class_id INT REFERENCES classes(id) ON DELETE CASCADE, student_id INT REFERENCES students(id) ON DELETE CASCADE, PRIMARY KEY(class_id,student_id));
CREATE TABLE IF NOT EXISTS attendance(id SERIAL PRIMARY KEY, class_id INT REFERENCES classes(id) ON DELETE CASCADE, student_id INT REFERENCES students(id) ON DELETE CASCADE, date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'present', UNIQUE(class_id,student_id,date));
CREATE TABLE IF NOT EXISTS grades(id SERIAL PRIMARY KEY, student_id INT REFERENCES students(id) ON DELETE CASCADE, class_id INT REFERENCES classes(id) ON DELETE CASCADE, subject TEXT NOT NULL, score TEXT NOT NULL, UNIQUE(student_id,class_id,subject));
